<?= $this->section('content') ?>
<?php $editable=$policy->allows($user,'edit',$lead)&&!$lead['archived_at']&&$lead['outcome']==='open'; ?>
<div class="page-heading"><div><div class="eyebrow">LEAD PROFILE / <?= esc($lead['code']) ?></div><h1><?= esc($lead['display_name']) ?></h1><p><?= esc(ucfirst($lead['type'])) ?> · <?= esc($lead['status_name']) ?><?= $lead['archived_at']?' · Archived':'' ?></p></div><div class="client-actions"><a class="btn btn-outline-light" href="<?= site_url('leads') ?>">All leads</a><?php if($editable): ?><a class="btn btn-teal" href="<?= site_url('leads/'.$lead['id'].'/edit') ?>">Edit lead</a><?php endif ?></div></div>
<?= view('clients/alerts') ?>
<?php if($lead['archived_at']||$lead['outcome']!=='open'): ?><div class="alert alert-warning" role="note">This lead is <?= $lead['archived_at']?'archived':'in a terminal pipeline status' ?>. Its information, contacts and addresses are read-only. Restore it or request authorized reopening of a lost lead before editing.</div><?php endif ?>
<div class="client-profile-grid"><section class="crm-card client-panel"><h2>Lead information</h2><dl class="client-details"><?php foreach(['code'=>'Lead code','type'=>'Type','company_name'=>'Company','first_name'=>'First name','last_name'=>'Last name','email'=>'Email','phone'=>'Phone','website'=>'Website','source_name'=>'Lead source','status_name'=>'Pipeline status','owner_name'=>'Assigned user','creator_name'=>'Created by','version'=>'Version','created_at'=>'Created','updated_at'=>'Updated'] as $key=>$label):if($lead[$key]===null)continue; ?><div><dt><?= esc($label) ?></dt><dd><?= esc((string)$lead[$key]) ?></dd></div><?php endforeach ?></dl><h3>Internal notes</h3><p class="client-notes"><?= esc($lead['notes']?:'No notes added.') ?></p><div class="client-actions"><?php if($policy->allows($user,'archive',$lead)): ?><form method="post" action="<?= site_url('leads/'.$lead['id'].($lead['archived_at']?'/restore':'/archive')) ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= (int)$lead['version'] ?>"><button class="btn btn-outline-warning" type="submit"><?= $lead['archived_at']?'Restore lead':'Archive lead' ?></button></form><?php endif ?><?php if(!$lead['archived_at']&&$lead['outcome']==='lost'&&$policy->allows($user,'reopen',$lead)): ?><form method="post" action="<?= site_url('leads/'.$lead['id'].'/reopen') ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= (int)$lead['version'] ?>"><button class="btn btn-teal" type="submit">Reopen lost lead</button></form><?php endif ?></div></section>
<div class="client-profile-sections"><?php foreach(['contacts'=>$contacts,'addresses'=>$addresses] as $kind=>$items): ?><section class="crm-card client-panel"><div class="client-section-heading"><h2><?= ucfirst($kind) ?></h2><?php if($editable): ?><a class="subtle-link" href="<?= site_url('leads/'.$lead['id'].'/'.$kind.'/new') ?>">+ Add <?= $kind==='contacts'?'contact':'address' ?></a><?php endif ?></div><?php foreach($items as $item): ?><article class="client-entry"><?php if($kind==='contacts'): ?><h3><?= esc($item['first_name'].' '.$item['last_name']) ?></h3><p><?= esc($item['job_title']??'') ?></p><p><?= esc($item['email']??'No email') ?> · <?= esc($item['phone']??'No phone') ?></p><?php else: ?><h3><?= esc(ucfirst($item['kind'])) ?> address</h3><address><?= esc($item['line1']) ?><br><?= esc($item['line2']??'') ?><br><?= esc($item['city'].', '.($item['region']??'').' '.($item['postal_code']??'')) ?><br><?= esc($item['country']) ?></address><?php endif ?><?php if($editable): ?><div class="client-actions"><a class="subtle-link" href="<?= site_url('leads/'.$lead['id'].'/'.$kind.'/'.$item['id'].'/edit') ?>">Edit</a><details class="client-remove"><summary>Remove</summary><form method="post" action="<?= site_url('leads/'.$lead['id'].'/'.$kind.'/'.$item['id'].'/remove') ?>"><?= csrf_field() ?><input type="hidden" name="version" value="<?= (int)$lead['version'] ?>"><p>Remove this entry from the lead?</p><button class="btn btn-outline-danger" type="submit">Confirm removal</button></form></details></div><?php endif ?></article><?php endforeach ?><?php if(!$items): ?><p class="text-secondary">No <?= $kind ?> added.</p><?php endif ?></section><?php endforeach ?>
<section class="crm-card client-panel"><h2>Activity history</h2><p class="text-secondary">Most recent 50 events. Each successful change creates one versioned event.</p><?php foreach($history as $event): ?><article class="client-entry"><h3><?= esc($event['summary']) ?></h3><p><?= esc($event['actor_name']) ?> · <?= esc($event['created_at']) ?> · Version <?= (int)$event['version'] ?></p><?php $meta=json_decode($event['metadata']??'{}',true)?:[];if(isset($meta['owner_from'])&&$meta['owner_from']!==$meta['owner_to']): ?><p>Assignment changed from <?= esc($meta['owner_from_name']??'Previous assignee') ?> to <?= esc($meta['owner_to_name']??'New assignee') ?>.</p><?php endif ?><?php if(isset($meta['status_from'])&&$meta['status_from']!==$meta['status_to']): ?><p>Pipeline status changed from <?= esc($meta['status_from_name']??'Previous status') ?> to <?= esc($meta['status_to_name']??'New status') ?>.</p><?php endif ?></article><?php endforeach ?></section><section class="crm-card client-panel"><h2>Pipeline & conversion</h2><a class="subtle-link" href="<?= site_url('leads/kanban') ?>">Open pipeline</a><?php if(!$lead['archived_at']&&$lead['status_slug']==='qualified'&&$policy->allows($user,'convert',$lead)&&$user->can('clients.view')): ?><p class="mt-3"><a class="btn btn-teal" href="<?= site_url('leads/'.$lead['id'].'/convert') ?>">Review conversion</a></p><?php elseif($lead['outcome']==='converted'): ?><?php if($conversion??null): ?><p class="mt-3"><a class="btn btn-teal" href="<?= site_url('leads/'.$lead['id'].'/conversion') ?>">View conversion result</a></p><?php else: ?><p class="conversion-note mt-3">This lead has been converted. Independent client permissions are required to view its destination.</p><?php endif ?><?php else: ?><p class="conversion-note mt-3">Only an unarchived Qualified lead may be converted.</p><?php endif ?></section></div></div>
<?= $this->endSection() ?>
